import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { environment } from '../../environments/environment';
import type {
  DashboardStats,
  Kpis,
  StatusBucket,
  TipoPersonaBucket,
  MonthlyTrendPoint,
  SemaforoResumen,
} from '../models/dashboard.model';

interface DashboardStatsResponse {
  kpis: Kpis;
  byStatus: StatusBucket[];
  byTipoPersona: TipoPersonaBucket[];
  monthlyTrend: MonthlyTrendPoint[];
  semaforoResumen: SemaforoResumen;
}

@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly http = inject(HttpClient);
  private readonly apiUrl = environment.apiUrl;

  private getFullUrl(path: string): string {
    const cleanPath = path.startsWith('/') ? path.substring(1) : path;
    if (this.apiUrl.endsWith('/api') || this.apiUrl === '/api') {
      if (cleanPath.startsWith('api/')) {
        return `${this.apiUrl}/${cleanPath.substring(4)}`;
      }
    }
    return `${this.apiUrl}/${cleanPath}`;
  }

  getStats(): Observable<DashboardStats> {
    return this.http
      .get<DashboardStatsResponse>(this.getFullUrl('api/dashboard/stats'))
      .pipe(map((res) => this.mapStats(res)));
  }

  private mapStats(raw: DashboardStatsResponse): DashboardStats {
    return {
      kpis: raw.kpis,
      byStatus: raw.byStatus,
      byTipoPersona: raw.byTipoPersona,
      monthlyTrend: raw.monthlyTrend,
      semaforoResumen: raw.semaforoResumen,
    };
  }
}
