import {Component, inject, computed, resource} from '@angular/core';
import {RouterLink} from '@angular/router';
import {firstValueFrom} from 'rxjs';
import {DashboardService} from '../../../services/dashboard.service';
import {VdinChartComponent} from '../../../shared/components/vdin-chart/vdin-chart.component';
import {resolveStatusColors, type BootstrapColorVar} from '../../../shared/theme-chart-colors';
import type {DashboardStats} from '../../../models/dashboard.model';

const STATUS_VAR_MAP: Record<string, BootstrapColorVar> = {
  Autorizada: '--bs-success',
  'No Autorizada': '--bs-danger',
  'En Dictaminación': '--bs-info',
  Subsanada: '--bs-warning',
  Enviada: '--bs-primary',
  Incompleta: '--bs-secondary',
  'No Presentada': '--bs-secondary',
  Suspendida: '--bs-secondary',
  Revocada: '--bs-secondary',
};

@Component({
  selector: 'app-ejecutivos-dashboard',
  imports: [RouterLink, VdinChartComponent],
  templateUrl: './dashboard.component.html',
  styleUrl: './dashboard.component.scss',
})
export class DashboardComponent {
  private readonly dashboardService = inject(DashboardService);

  readonly statsResource = resource({
    loader: () => firstValueFrom(this.dashboardService.getStats()),
  });

  readonly stats = computed<DashboardStats | null>(() =>
    this.statsResource.hasValue() ? this.statsResource.value()! : null,
  );

  readonly isLoading = computed(() => this.statsResource.isLoading());

  readonly kpiTotal = computed(() => this.stats()?.kpis.total ?? 0);
  readonly kpiActivas = computed(() => this.stats()?.kpis.activas ?? 0);
  readonly kpiPendientes = computed(() => this.stats()?.kpis.pendientes ?? 0);
  readonly kpiCompletadas = computed(() => this.stats()?.kpis.completadas ?? 0);
  readonly kpiInactivas = computed(() => this.stats()?.kpis.inactivas ?? 0);

  readonly semaforoVerdes = computed(() => this.stats()?.semaforoResumen.verdes ?? 0);
  readonly semaforoAmarillas = computed(() => this.stats()?.semaforoResumen.amarillas ?? 0);
  readonly semaforoNaranjas = computed(() => this.stats()?.semaforoResumen.naranjas ?? 0);
  readonly semaforoRojas = computed(() => this.stats()?.semaforoResumen.rojas ?? 0);

  readonly statusChartData = computed(() => {
    const data = this.stats()?.byStatus;
    if (!data?.length) {
      return {labels: [] as string[], datasets: [{data: [] as number[], backgroundColor: [] as string[], borderColor: [] as string[], hoverBackgroundColor: [] as string[]}]};
    }

    const statuses = data.map((b) => b.status);
    const colors = resolveStatusColors(statuses, 'doughnut');

    return {
      labels: statuses,
      datasets: [
        {
          label: 'Por estatus',
          data: data.map((b) => b.count),
          backgroundColor: colors.backgroundColor,
          borderColor: colors.borderColor,
          hoverBackgroundColor: colors.hoverBackgroundColor,
          __colorVars: statuses.map((s) => (STATUS_VAR_MAP[s] ?? '--bs-secondary') as BootstrapColorVar),
        },
      ],
    };
  });

  readonly tipoPersonaChartData = computed(() => {
    const data = this.stats()?.byTipoPersona;
    if (!data?.length) {
      return {labels: [] as string[], datasets: [{data: [] as number[], backgroundColor: [] as string[], borderColor: [] as string[]}]};
    }

    const colorVars: BootstrapColorVar[] = data.map((b) =>
      b.tipo === 'fisica' ? '--bs-primary' : '--bs-secondary',
    );

    return {
      labels: data.map((b) => (b.tipo === 'fisica' ? 'Persona Física' : 'Moral')),
      datasets: [
        {
          label: 'Por tipo de persona',
          data: data.map((b) => b.count),
          backgroundColor: colorVars.map((v) => `var(${v})`),
          borderColor: colorVars.map((v) => `var(${v})`),
          __colorVars: colorVars,
        },
      ],
    };
  });

  readonly monthlyTrendChartData = computed(() => {
    const data = this.stats()?.monthlyTrend;
    if (!data?.length) {
      return {labels: [] as string[], datasets: [{data: [] as number[]}]};
    }

    return {
      labels: data.map((p) => p.label),
      datasets: [
        {
          label: 'Solicitudes',
          data: data.map((p) => p.count),
          __colorVars: ['--bs-primary'] as BootstrapColorVar[],
        },
      ],
    };
  });
}
